def solve(data):
    cutoff = int(data.get('cutoff', 10**9))
    rounding = data.get('rounding', 'floor')
    winners = {}

    for position, event in enumerate(data['events']):
        if int(event.get('sequence', 0)) > cutoff:
            continue

        if 'id' in event:
            identity = ('id', event['id'])
        else:
            identity = ('anonymous', position)

        revision = int(event.get('revision', 0))
        previous = winners.get(identity)
        if previous is None or revision >= previous[0]:
            winners[identity] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in sorted(winners.values(), key=lambda winner: winner[1]):
        if event.get('void') is True:
            continue

        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        value = amount(event, rounding)
        if event.get('kind') == 'refund':
            value = -value
        balances[key] = balances.get(key, 0) + value

    return {'balances': balances}
